// Builds supabase/setup-all.sql: every migration, then the seeds, in the order they must run.
// Paste the result into the Supabase SQL Editor of a new project. Every file in it is safe to re-run.
// npm run db:bundle
import fs from "node:fs";
import path from "node:path";

const root = path.resolve("supabase");
const migrations = fs.readdirSync(path.join(root, "migrations")).filter((f) => f.endsWith(".sql")).sort();
const seeds = ["team.sql", "accounts.sql"];
const parts = [
  "-- Bedaya: full database setup (generated by scripts/bundle-sql.mjs; do not edit by hand).",
  "-- Paste into the Supabase SQL Editor and run. Order: migrations, then seeds. Safe to re-run.",
  "-- After running, set SUPABASE_SECRET_KEY (server only) in the app's environment for Login with SANAD.",
  "",
];
for (const f of migrations) parts.push(`-- ================================================================ migrations/${f}`, fs.readFileSync(path.join(root, "migrations", f), "utf8").trim(), "");
for (const f of seeds) parts.push(`-- ================================================================ seeds/${f}`, fs.readFileSync(path.join(root, "seeds", f), "utf8").trim(), "");
fs.writeFileSync(path.join(root, "setup-all.sql"), `${parts.join("\n")}\n`);
console.log(`supabase/setup-all.sql: ${migrations.length} migrations + ${seeds.length} seeds`);
